324	    private Set<String> extractCcpaEnforcedBidders(List<String> bidders, BidRequest bidRequest, BidderAliases aliases) {
325	        final Set<String> ccpaEnforcedBidders = new HashSet<>(bidders);
326	
327	        final ExtRequest extBidRequest = bidRequest.getExt();
328	        final ExtRequestPrebid extRequestPrebid = extBidRequest != null ? extBidRequest.getPrebid() : null;
329	        final List<String> nosaleBidders = extRequestPrebid != null
330	                ? ListUtils.emptyIfNull(extRequestPrebid.getNosale())
331	                : Collections.emptyList();
332	
333	        if (nosaleBidders.size() == 1 && nosaleBidders.contains(CATCH_ALL_BIDDERS)) {
334	            ccpaEnforcedBidders.clear();
335	        } else {
336	            ccpaEnforcedBidders.removeAll(nosaleBidders);
337	        }
338	
339	        ccpaEnforcedBidders.removeIf(bidder ->
340	                !bidderCatalog.bidderInfoByName(aliases.resolveBidder(bidder)).isCcpaEnforced());
341	
342	        return ccpaEnforcedBidders;
343	    }
