                    aliases.resolveBidder(bidder),
                    requestType,
                    userIdRemoved,
                    geoMasked,
                    analyticsBlocked,
                    requestBlocked);
        }

        if (lmtEnforce && isLmtEnabled(device)) {
            metrics.updatePrivacyLmtMetric();
        }

        return bidderToEnforcement;
    }

